/bin/bash -lc "cat <<'EOF' > app/components/server-timestamp.tsx
import { connection } from 'next/server';

export default async function ServerTimestamp() {
  await connection();
  const now = new Date();
  const isoTimestamp = now.toISOString();

  return <time dateTime={isoTimestamp}>{isoTimestamp}</time>;
}
EOF"

